entries[113985] = { ["name"] = "Summender Schwarzeisenzünder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, 10 Sek. lang 'Detonation' auszulösen. Während 'Detonation' aktiv ist, erhaltet Ihr alle 0.5 Sek. 2 kritischen Trefferwert. Dieser Effekt ist bis zu 20-mal stapelbar. (Ungefähr 0.92 Auslösungen pro Minute)\nVerkaufspreis:" }
entries[113986] = { ["name"] = "Dampfkessel mit automatischer Reparatur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 13 Vielseitigkeit\nAnlegen: Eure Zauber haben eine Chance, für 10 Sek. 'Sterilisieren' auszulösen. Während 'Sterilisieren' aktiv ist, erhaltet Ihr alle 0.5 Sek. 2 Tempo. Dieser Effekt ist bis zu 20-mal stapelbar. (Ungefähr 0.92 Auslösungen pro Minute)\nVerkaufspreis:" }
