entries[114121] = { ["name"] = "Brokyos Ring", ["text"] = "Questgegenstand\n\"Greblin könnte sich dafür interessieren.\"" }
entries[114124] = { ["name"] = "Phantomtrank", ["text"] = "Ashran\nWird beim Aufheben gebunden\nBenutzen: Gewährt dem Trinkenden Unsichtbarkeit und erhöht seine Bewegungsgeschwindigkeit 25 Sek. lang um 30%. Kann beim Reiten verwendet werden. Kann nur in Ashran verwendet werden. (5 Min Abklingzeit)" }
entries[114125] = { ["name"] = "Gespeicherter Diskombobulatorstrahl", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Zwingt Euer Ziel zum Absteigen und verringert 5 Sek. lang dessen Kampfeffektivität. (1 Min Abklingzeit)\n5 Aufladungen" }
entries[114126] = { ["name"] = "Einwegtaschenflugmaschine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Beschwört eine Taschenflugmaschine, die Eure Artefaktfragmente zurück zur Sturmschildfeste bringt, wofür Ihr entsprechend Ehre und Ruf erhaltet.\n\nEure Artefaktfragmente werden gleichmäßig auf die verfügbaren Ziele der Allianz verteilt. (2 Std. Abklingzeit)\n5 Aufladungen\nBenötigt Wrynns Vorhut\n- Freundlich\nVerkaufspreis:" }
entries[114128] = { ["name"] = "Ausgeglichene Waffenverbesserung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wertet die Waffe eines Anhängers um 3 Machtstufen auf.\nVerkaufspreis:" }
