entries[114131] = { ["name"] = "Extreme Waffenverbesserung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wertet die Waffe eines Anhängers um 9 Machtstufen auf.\nVerkaufspreis:" }
entries[114137] = { ["name"] = "Energiekern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (100)\n\"Die Arakkoa beherrschten den Umgang mit lichtbasierten Technologien meisterhaft. Dieser Energiekern ist ein Artefakt aus der Zeit vor dem mysteriösen Untergang dieser vergessenen Zivilisation. Der Kern könnte immer noch funktionstüchtig sein.\"\nVerkaufspreis:" }
entries[114138] = { ["name"] = "Lebenskern", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine mit Blättern bedeckte Kugel, die im Einklang mit Eurem Herz pulsiert.\"" }
