entries[114225] = { ["name"] = "Vergessenes Apexisschmuckstück", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Der Zaubernde stellt ein Apexisschmuckstück her, das allen Verbündeten in der Nähe Energie spendet. (1 Min Abklingzeit)\n\"Dieses staubige Schmuckstück pulsiert noch immer voller Macht. Bei Verwendung wird dieser Gegenstand in der Nähe auf dem Boden platziert und gewährt Euch und Euren Verbündeten erhöhte Ressourcenregeneration.\"\nVerkaufspreis:" }
entries[114227] = { ["name"] = "Blubberblasenzauberstab", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Verschießt 5 Sek. lang einen Strahl aus Blubberblasen. (5 Sek. Abklingzeit)\n\"Ein Kinderspielzeug, das man oft auf Kinderfeiern oder in den Händen eines wütenden Wasserelementars sehen kann.\"\nVerkaufspreis:" }
entries[114229] = { ["name"] = "Skothwas Auge", ["text"] = "Questgegenstand\n\"Schön glibberig.\"" }
