entries[114238] = { ["name"] = "Gewürzte Stachelforelle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nDauer: 3 std. (Realzeit)\nBenutzen: Das Verspeisen dieses Arakkoagerichts erhöht Eure Vielseitigkeit 30 Min. lang um 14 .\n\nDieser Stärkungseffekt bleibt nur bestehen, solange Ihr Euch im Bereich der Ruinen von Skettis der Spitzen von Arak befindet.\n\"Das Filet einer Stachelforelle, durchzogen von den subtilen Gewürzen der Arakkoa.\"\nVerkaufspreis:" }
entries[114240] = { ["name"] = "Verderbtes Blut von Teron'gor", ["text"] = "Questgegenstand\nEinzigartig\n\"Hat einen ungesunden, widerlich grünen Farbton, ähnlich wie Galle.\"" }
entries[114241] = { ["name"] = "Verschlissene Rüstungsfetzen", ["text"] = "Questgegenstand\n\"Beweis, dass Ihr einen Feind auf dem Schlachtfeld getötet habt.\"" }
entries[114242] = { ["name"] = "Abu'gars Lebenskraft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine ausgezeichnete Angelrute, hergestellt von dem Troll Abu'Gar. Ohne eine Spule ist sie jedoch relativ nutzlos.\"" }
entries[114243] = { ["name"] = "Abu'gars beste Angelspule", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit einer passenden Angelrute wäre diese Angelspule ideal für einen richtig dicken Fang.\"" }
entries[114244] = { ["name"] = "Mikrojetpack GG-117", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Lässt Euren Sprung feurig werden. Fügt Gegnern am Einschlagsort Feuerschaden zu und stößt sie zu Boden. (1.5s Abklingzeit) (10 Sek. Abklingzeit)\n3 Aufladungen\n\"Vorsicht: Vom Gesicht weg zielen.\"" }
entries[114245] = { ["name"] = "Abu'gars Lieblingsköder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Voodoomagie, die davon ausgeht ist fast greifbar!\"" }
entries[114246] = { ["name"] = "Personentransportsystem \"Himmelsschreck\"", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Schleudert Euch hoch in die Luft und breitet einen mechanischen Gleiter aus. (5 Sek. Abklingzeit)\n3 Aufladungen\n\"Inhalt: Rakete, Gleiter, Haftungsausschluss.\"" }
